package cn.edu.travel;

import java.util.*;
import java.time.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import static cn.edu.travel.ApiController.*;

/** 提醒、体检与旅行分享；公开输出使用显式字段，私人预算和备注不参与分享。 */
@RestController
@RequestMapping("/api")
public class ExperienceController {
    final Database db;final Auth auth;
    public ExperienceController(Database db,Auth auth){this.db=db;this.auth=auth;}
    Map<String,Object> own(long id,HttpServletRequest req){var u=auth.require(req);return db.one("SELECT * FROM trips WHERE id=? AND user_id=?",id,u.get("id"));}
    List<Map<String,Object>> stops(long id){return db.list("SELECT i.spot_id,i.day_number,i.sort_order,s.title,s.city_id,s.image,s.published,s.theme,s.duration_minutes,c.name AS city_name FROM trip_items i JOIN spots s ON s.id=i.spot_id JOIN cities c ON c.id=s.city_id WHERE i.trip_id=? ORDER BY i.day_number,i.sort_order",id);}
    @GetMapping("/me/notifications") Object notifications(HttpServletRequest req){var u=auth.require(req);return Map.of("items",db.list("SELECT id,kind,title,body,path,seen,created_at FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100",u.get("id")),"unread",db.count("SELECT count(*) FROM notifications WHERE user_id=? AND seen=0",u.get("id")));}
    @PutMapping("/me/notifications/read") Object read(@RequestBody Map<String,Object> b,HttpServletRequest req){var u=auth.require(req);if(Boolean.TRUE.equals(b.get("all")))db.update("UPDATE notifications SET seen=1 WHERE user_id=?",u.get("id"));else{long id=number(b.get("id"));if(db.update("UPDATE notifications SET seen=1 WHERE id=? AND user_id=?",id,u.get("id"))==0)throw new ApiError(404,"没有这条消息");}return Map.of("message","消息已标为已读");}
    @GetMapping("/me/trips/{id}/experience") Object experience(@PathVariable long id,HttpServletRequest req){var t=own(id,req);var out=new LinkedHashMap<String,Object>();out.put("trip_id",id);out.put("review",review(t,stops(id)));var p=db.list("SELECT id,title,description,status,blocked,revision,source_revision,days FROM shared_routes WHERE source_trip_id=?",id);if(!p.isEmpty())p.get(0).put("source_changed",sourceChanged(p.get(0),t));out.put("publication",p.isEmpty()?null:p.get(0));var m=db.list("SELECT * FROM travel_memories WHERE trip_id=?",id);out.put("memory",m.isEmpty()?null:memory(m.get(0)));return out;}
    Object review(Map<String,Object> t,List<Map<String,Object>> items){List<Map<String,Object>> issues=new ArrayList<>(),days=new ArrayList<>();int count=(int)number(t.get("days"));
        for(int d=1;d<=count;d++){final int day=d;var rows=items.stream().filter(i->number(i.get("day_number"))==day).toList();long minutes=rows.stream().mapToLong(i->number(i.get("duration_minutes"))).sum();var cities=new LinkedHashSet<String>();for(var s:rows)cities.add(s.get("city_name").toString());days.add(Map.of("day",d,"minutes",minutes,"count",rows.size(),"cities",cities));
            if(rows.isEmpty())issues.add(issue("info",d,"这一天还没有安排景点","可以保留为自由时间，也可以从收藏或景点对比中补充。"));
            if(minutes>480)issues.add(issue("warning",d,"建议停留时间超过 8 小时","当前景点建议时长合计 "+minutes+" 分钟，可移动部分景点到其他天。"));else if(minutes>=360)issues.add(issue("info",d,"这一天的安排较满","景点建议时长合计 "+minutes+" 分钟，记得给交通、用餐和休息留时间。"));
            if(cities.size()>1)issues.add(issue("warning",d,"同一天包含多个城市","涉及 "+String.join("、",cities)+"，请确认城际交通与实际可用时间。"));
            for(var s:rows)if(number(s.get("published"))==0)issues.add(issue("warning",d,s.get("title")+"已下架","这项安排仍保留，可用景点对比选择替代地点。"));
        }
        long id=number(t.get("id"));long balance=db.count("SELECT coalesce(sum(planned_cents-actual_cents),0) FROM trip_budget_items WHERE trip_id=?",id);if(balance<0)issues.add(issue("warning",0,"当前实际花费超过预算","打开下方预算明细，检查超支项目并按实际情况调整。"));
        return Map.of("issues",issues,"days",days,"warning_count",issues.stream().filter(i->"warning".equals(i.get("severity"))).count());
    }
    Map<String,Object> issue(String severity,int day,String title,String message){return Map.of("severity",severity,"day",day,"title",title,"message",message);}
    @PostMapping("/me/trips/{id}/publish") Object publish(@PathVariable long id,@RequestBody Map<String,Object> b,HttpServletRequest req){var user=auth.require(req);long sourceRevision=number(b.get("trip_revision"));if(sourceRevision<1)throw new ApiError(400,"请重新预览行程后发布");return db.transaction(status->{if(db.update("UPDATE trips SET revision=revision WHERE id=? AND user_id=? AND revision=?",id,user.get("id"),sourceRevision)==0){own(id,req);throw new ApiError(409,"行程已发生变化，请重新载入预览后再发布");}var t=own(id,req);if(!Boolean.TRUE.equals(b.get("confirm_public")))throw new ApiError(400,"请先确认发布预览");String title=text(b,"title",3,80),description=text(b,"description",0,600);long revision=number(b.getOrDefault("revision",0));var items=stops(id);if(items.isEmpty())throw new ApiError(400,"请至少安排一个景点后再发布");if(items.stream().anyMatch(s->number(s.get("published"))==0))throw new ApiError(400,"行程含已下架景点，请先调整后发布");long routeId;
        var rows=db.list("SELECT * FROM shared_routes WHERE source_trip_id=?",id);
        if(rows.isEmpty()){if(revision!=0)throw new ApiError(409,"公开路线已更新，请刷新后重试");routeId=db.insert("INSERT INTO shared_routes(source_trip_id,user_id,title,description,days,source_revision) VALUES(?,?,?,?,?,?)",id,t.get("user_id"),title,description,t.get("days"),t.get("revision"));}
        else{var r=rows.get(0);routeId=number(r.get("id"));if(number(r.get("blocked"))==1)throw new ApiError(409,"这条路线已由管理员下架，请联系管理员处理");if(db.update("UPDATE shared_routes SET title=?,description=?,days=?,source_revision=?,status='PUBLISHED',revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=? AND revision=?",title,description,t.get("days"),t.get("revision"),routeId,revision)==0)throw new ApiError(409,"公开路线已更新，请刷新后重试");db.update("DELETE FROM shared_route_stops WHERE route_id=?",routeId);}
        int order=0;for(var s:items)db.update("INSERT INTO shared_route_stops(route_id,spot_id,day_number,sort_order) VALUES(?,?,?,?)",routeId,s.get("spot_id"),s.get("day_number"),order++);return Map.of("id",routeId,"message","路线已公开，预算和私人备注保留在个人行程中");});}
    String routeSelect="SELECT r.id,r.title,r.description,r.days,r.status,r.blocked,r.revision,r.created_at,r.updated_at,u.username FROM shared_routes r JOIN users u ON u.id=r.user_id";
    @GetMapping("/routes") Object routes(@RequestParam(defaultValue="0") long city,@RequestParam(defaultValue="0") int days,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="1") int page){q=q.trim();if(q.length()>100||days<0||days>14)throw new ApiError(400,"筛选条件不正确");String like="%"+q.replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%";String where=" WHERE r.status='PUBLISHED' AND r.blocked=0 AND (?=0 OR r.days=?) AND (?=0 OR EXISTS(SELECT 1 FROM shared_route_stops z JOIN spots s ON s.id=z.spot_id WHERE z.route_id=r.id AND s.city_id=?)) AND (r.title LIKE ? ESCAPE '\\' OR r.description LIKE ? ESCAPE '\\')";Object[] args={days,days,city,city,like,like};long total=db.count("SELECT count(*) FROM shared_routes r"+where,args);page=Math.max(1,Math.min(100000,page));var params=new ArrayList<>(Arrays.asList(args));params.add(6);params.add((page-1)*6);var items=db.list(routeSelect+where+" ORDER BY r.id DESC LIMIT ? OFFSET ?",params.toArray());for(var r:items)r.put("items",routeStops(number(r.get("id"))));return Map.of("items",items,"total",total,"page",page,"size",6);}
    List<Map<String,Object>> routeStops(long id){return db.list("SELECT z.spot_id,z.day_number,z.sort_order,s.title,s.city_id,s.image,s.published,s.theme,s.duration_minutes,c.name AS city_name FROM shared_route_stops z JOIN spots s ON s.id=z.spot_id JOIN cities c ON c.id=s.city_id WHERE z.route_id=? ORDER BY z.day_number,z.sort_order",id);}
    Map<String,Object> publicRoute(long id){var r=db.one(routeSelect+" WHERE r.id=? AND r.status='PUBLISHED' AND r.blocked=0",id);r.put("items",routeStops(id));return r;}
    @GetMapping("/routes/{id}") Object route(@PathVariable long id){return publicRoute(id);}
    @PostMapping("/routes/{id}/copy") Object copy(@PathVariable long id,@RequestBody Map<String,Object> b,HttpServletRequest req){var u=auth.require(req);return db.transaction(status->{var r=publicRoute(id);var items=routeStops(id);if(items.isEmpty()||items.stream().anyMatch(s->number(s.get("published"))==0))throw new ApiError(409,"路线含暂不可用的景点，请选择其他路线");if(db.count("SELECT count(*) FROM trips WHERE user_id=?",u.get("id"))>=30)throw new ApiError(400,"最多保留30份行程，请先整理");String title=Objects.toString(b.get("title"),r.get("title")+"（副本）").trim();if(title.isEmpty()||title.length()>60)throw new ApiError(400,"新行程名称请填写1～60字");long key=db.insert("INSERT INTO trips(user_id,title,days) VALUES(?,?,?)",u.get("id"),title,r.get("days"));int order=0;for(var s:items)db.update("INSERT INTO trip_items(trip_id,spot_id,day_number,sort_order,note) VALUES(?,?,?,?,?)",key,s.get("spot_id"),s.get("day_number"),order++,"");TripVersions.capture(db,key,"CREATE",0);return Map.of("id",key,"message","已复制到我的行程");});}
    boolean sourceChanged(Map<String,Object> r,Map<String,Object> t){
        if(number(r.get("days"))!=number(t.get("days")))return true;
        var current=db.list("SELECT spot_id,day_number FROM trip_items WHERE trip_id=? ORDER BY day_number,sort_order",t.get("id"));
        var published=db.list("SELECT spot_id,day_number FROM shared_route_stops WHERE route_id=? ORDER BY day_number,sort_order",r.get("id"));
        return !current.equals(published);
    }
    @GetMapping("/me/routes") Object mineRoutes(HttpServletRequest req){var u=auth.require(req);var rows=db.list(routeSelect+" WHERE r.user_id=? ORDER BY r.id DESC",u.get("id"));for(var r:rows){var t=db.one("SELECT t.* FROM trips t JOIN shared_routes r ON r.source_trip_id=t.id WHERE r.id=? AND t.user_id=?",r.get("id"),u.get("id"));r.put("source_trip_id",t.get("id"));r.put("source_changed",sourceChanged(r,t));}return rows;}
    @PutMapping("/me/routes/{id}/status") Object routeStatus(@PathVariable long id,@RequestBody Map<String,Object> b,HttpServletRequest req){var u=auth.require(req);var r=db.one("SELECT * FROM shared_routes WHERE id=? AND user_id=?",id,u.get("id"));String status=text(b,"status",1,20);if(!Set.of("PUBLISHED","PRIVATE").contains(status))throw new ApiError(400,"状态不正确");if(status.equals("PUBLISHED")&&number(r.get("blocked"))==1)throw new ApiError(409,"路线已由管理员下架");if(db.update("UPDATE shared_routes SET status=?,revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=? AND revision=?",status,id,number(b.get("revision")))==0)throw new ApiError(409,"路线已更新，请刷新后再试");return Map.of("message",status.equals("PRIVATE")?"路线已撤回公开":"路线已公开");}
    @GetMapping("/admin/routes") Object adminRoutes(HttpServletRequest req){auth.admin(req);return db.list(routeSelect+" WHERE r.status='PUBLISHED' OR r.blocked=1 ORDER BY r.id DESC");}
    @PutMapping("/admin/routes/{id}/moderation") Object moderate(@PathVariable long id,@RequestBody Map<String,Object> b,HttpServletRequest req){auth.admin(req);db.one("SELECT id FROM shared_routes WHERE id=? AND (status='PUBLISHED' OR blocked=1)",id);if(!(b.get("blocked") instanceof Boolean))throw new ApiError(400,"管理状态不正确");db.update("UPDATE shared_routes SET blocked=?,revision=revision+1 WHERE id=?",Boolean.TRUE.equals(b.get("blocked"))?1:0,id);return Map.of("message",Boolean.TRUE.equals(b.get("blocked"))?"路线已下架":"路线已恢复");}
    Map<String,Object> memory(Map<String,Object> m){var out=new LinkedHashMap<>(m);out.put("snapshot",db.decode(m.get("snapshot")));return out;}
    @PutMapping("/me/trips/{id}/memory") Object remember(@PathVariable long id,@RequestBody Map<String,Object> b,HttpServletRequest req){return db.transaction(status->{var t=own(id,req);String date=text(b,"completed_on",10,10),note=text(b,"note",0,1200);try{LocalDate d=LocalDate.parse(date);if(!d.toString().equals(date)||d.isAfter(LocalDate.now(ZoneId.of("Asia/Shanghai"))))throw new IllegalArgumentException();}catch(Exception e){throw new ApiError(400,"完成日期请选择今天或更早的有效日期");}var items=stops(id);if(items.isEmpty())throw new ApiError(400,"请先安排行程中的景点");var snapshot=Map.of("title",t.get("title"),"days",t.get("days"),"items",items);long revision=number(b.getOrDefault("revision",0));int changed;if(revision==0)changed=db.update("INSERT OR IGNORE INTO travel_memories(trip_id,completed_on,note,snapshot) VALUES(?,?,?,?)",id,date,note,db.encode(snapshot));else changed=db.update("UPDATE travel_memories SET completed_on=?,note=?,snapshot=?,revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE trip_id=? AND revision=?",date,note,db.encode(snapshot),id,revision);if(changed==0)throw new ApiError(409,"回忆记录已更新，请刷新后再试");return Map.of("message","旅行足迹已保存");});}
    @DeleteMapping("/me/trips/{id}/memory") Object forget(@PathVariable long id,HttpServletRequest req){own(id,req);db.update("DELETE FROM travel_memories WHERE trip_id=?",id);return Map.of("message","已取消完成标记");}
    @GetMapping("/me/memories") Object memories(HttpServletRequest req){var u=auth.require(req);var rows=db.list("SELECT m.* FROM travel_memories m JOIN trips t ON t.id=m.trip_id WHERE t.user_id=? ORDER BY completed_on DESC,trip_id DESC",u.get("id"));return rows.stream().map(this::memory).toList();}
    @GetMapping("/recommendations") Object recommendations(@RequestParam long city,@RequestParam(defaultValue="1") int days,@RequestParam(defaultValue="") String theme,@RequestParam(defaultValue="relaxed") String pace){if(days<1||days>7||!Set.of("relaxed","normal","full").contains(pace)||(!theme.isEmpty()&&!Set.of("山水风景","街巷生活","人文历史").contains(theme)))throw new ApiError(400,"请选择有效的推荐条件");var c=db.one("SELECT id,name FROM cities WHERE id=? AND published=1",city);int limit=pace.equals("relaxed")?240:pace.equals("normal")?360:480;var rows=db.list("SELECT s.id AS spot_id,s.title,s.theme,s.image,s.duration_minutes,c.name AS city_name FROM spots s JOIN cities c ON c.id=s.city_id WHERE s.city_id=? AND s.published=1 AND c.published=1 ORDER BY CASE WHEN s.theme=? THEN 0 ELSE 1 END,s.duration_minutes,s.id",city,theme);long[] loads=new long[days];int[] counts=new int[days];List<Map<String,Object>> picked=new ArrayList<>();for(var s:rows){int best=-1;long minutes=number(s.get("duration_minutes"));for(int d=0;d<days;d++)if(counts[d]<(pace.equals("relaxed")?2:3)&&(loads[d]+minutes<=limit||counts[d]==0)&&(best<0||loads[d]<loads[best]))best=d;if(best<0)continue;loads[best]+=minutes;counts[best]++;s.put("day_number",best+1);s.put("reason",(!theme.isEmpty()&&theme.equals(s.get("theme"))?"符合你选择的主题；":"同城补充选择；")+"建议停留 "+minutes+" 分钟"+(loads[best]>limit?"，这一站超过当前节奏的时长目标，可自行调整。":"，按当前游玩节奏分配。"));picked.add(s);}picked.sort(Comparator.comparingLong(s->number(s.get("day_number"))));return Map.of("city",c,"days",days,"theme",theme,"pace",pace,"items",picked,"available_count",rows.size(),"target_minutes_per_day",limit);}
}
